document.querySelectorAll('.load-animation').forEach(button=>button.addEventListener('click',()=>{const host=document.getElementById(button.dataset.host);if(!host.firstChild){const frame=document.createElement('iframe');frame.src=button.dataset.src;frame.title=button.dataset.title+' with playback controls';host.append(frame);}button.textContent='Animation loaded';button.disabled=true;host.scrollIntoView({block:'start'});}));
const sections=document.querySelectorAll('main section');
const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){document.querySelectorAll('nav a').forEach(a=>{const current=a.hash==='#'+entry.target.id;a.classList.toggle('active',current);if(current)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}}},{rootMargin:'-15% 0px -65% 0px'});sections.forEach(s=>observer.observe(s));
